#!/usr/bin/env python3
# Generated by Claude Opus 5 (Anthropic)
"""dag_index — the full index over everything FISH extracted for a session's GPU
DAGs, in the April-2026 index.html style: one summary table over all callbacks,
then per callback the skeleton/conditional pair and every observed signature.

It only indexes; the figures themselves come from
  postprocess/dag_signatures.py   ->  <session>_signatures/
  postprocess/dag_conditional.py  ->  <session>_conditional/

Usage:
  python3 -m postprocess.dag_index <session> [<session> ...] [--top]
  --top   also rebuild paper/dag_gallery/index.html over all sessions found
"""
from __future__ import annotations
import argparse, collections, html, json, os, sys
HERE = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, HERE)
import psycopg2, psycopg2.extras
from dag_conditional import analyse, tok, disp, CLASS_COLOR

DSN = os.environ.get('FISH_PG_DSN', 'host=localhost port=5432 dbname=fish user=fish password=fish')
ROOT = os.path.join('paper', 'dag_gallery')

CSS = """
body{font-family:system-ui,sans-serif;max-width:1600px;margin:1em auto;color:#222;padding:0 1em}
h1{font-size:1.5em;margin-bottom:.3em} h2{font-size:1.05em;margin:.2em 0;color:#1a5490}
.meta{color:#666;font-size:.85em;margin-bottom:.8em}
.cb{border:1px solid #ddd;border-radius:6px;padding:.8em 1em;margin-bottom:1em;background:#fafafa}
.stats{display:inline-block;margin-right:.4em;padding:2px 8px;background:#e3f2fd;border-radius:3px;
       font-family:ui-monospace,Menlo,monospace;font-size:.85em}
.stats.alt{background:#fff3e0} .stats.gold{background:#fff8e1} .stats.grey{background:#eee}
.label{font-family:ui-monospace,Menlo,monospace;font-size:.78em;color:#555;word-break:break-all;margin:.4em 0 .6em}
.nick{font-weight:600;color:#2e7d32}
.figs{display:flex;gap:8px;flex-wrap:wrap}
.fig{flex:1;min-width:340px;max-width:520px}
.fig img{width:100%;height:auto;border:1px solid #ccc;border-radius:4px;cursor:pointer;background:#fff}
.fig img:hover{border-color:#1a5490}
.fig-cap{font-size:.78em;color:#666;text-align:center;margin:2px 0}
table{border-collapse:collapse;margin:.5em 0 1.5em}
th,td{border:1px solid #ccc;padding:4px 8px;font-size:.88em}
th{background:#eee;position:sticky;top:0}
tr:nth-child(even) td{background:#fafafa}
a{color:#1a5490} code{font-size:.85em}
.num{text-align:right;font-family:ui-monospace,Menlo,monospace}
"""


def chips(counter):
    return ''.join(f'<span style="background:{CLASS_COLOR.get(c, "#777")};color:#fff;border-radius:3px;'
                   f'padding:1px 6px;margin-right:4px;font-size:.8em;white-space:nowrap">{c} {n}</span>'
                   for c, n in counter.most_common())


def sig_file(sigdir, tag, i, sig):
    """File name dag_signatures.py gave this signature, if it drew it."""
    p = f'{tag}_sig{i}_{str(sig)[:12]}.svg'
    return p if os.path.exists(os.path.join(sigdir, p)) else None


def session_index(session, scope='__main__', root=ROOT):
    conn = psycopg2.connect(DSN, cursor_factory=psycopg2.extras.RealDictCursor); conn.autocommit = True
    cur = conn.cursor()
    cur.execute("""SELECT anchor_type, anchor, node, entity, n_invocations, n_shapes, dags FROM gpu_dags
                   WHERE session_id=%s AND scope=%s ORDER BY n_invocations DESC""", (session, scope))
    rows = cur.fetchall()
    sigdir_rel, conddir_rel = session + '_signatures', session + '_conditional'
    sigdir, conddir = os.path.join(root, sigdir_rel), os.path.join(root, conddir_rel)

    rowsum = []          # table rows
    sections = []        # per-callback blocks
    tot = dict(inv=0, ops=0, cpu=0, sm=0, ce=0, sigs=0)
    kernels, copies = collections.Counter(), collections.Counter()

    for k, r in enumerate(rows, 1):
        shapes = r['dags'] if isinstance(r['dags'], list) else json.loads(r['dags'])
        shapes = sorted(shapes, key=lambda x: -int(x.get('count') or 0))
        nick = (f"{r['node']} ← {r['entity']}" if r['entity'] else r['node']) or f"thread {r['anchor']}"
        tag = f"{r['anchor_type']}_{str(r['anchor']).replace('0x','').lower()}"
        A = analyse(shapes)
        cls = (A or {}).get('cls', {})
        by_cls = collections.Counter(d['cls'] for d in (A or {}).get('sigs', []))
        n_all = sum(int(s.get('count') or 0) for s in shapes)
        dom = next((s for s in shapes if s.get('nodes')), shapes[0])
        dnodes = dom.get('nodes') or []
        pe = collections.Counter(n['pe'] for n in dnodes)
        phases = collections.Counter()
        for s in shapes:
            for ph, c in (s.get('phase_counts') or {}).items():
                phases[ph] += int(c)
        # session-wide GPU operation accounting (count-weighted over all shapes)
        for s in shapes:
            c = int(s.get('count') or 0)
            for n in (s.get('nodes') or []):
                tot['ops'] += c
                tot[n['pe'].lower()] = tot.get(n['pe'].lower(), 0) + c
                if n['pe'] == 'SM':
                    kernels[(n.get('name') or '?')] += c
                elif n['pe'] == 'CE':
                    copies[(n.get('name') or '?')] += c
        tot['inv'] += r['n_invocations'] or 0
        tot['sigs'] += len(shapes)

        # ---- figures ---------------------------------------------------
        figs, sig_links = [], []
        for name, cap in ((f'{tag}_fig1.svg', 'fig1: backbone + collapsed branches'),
                          (f'{tag}_fig2.svg', 'fig2: conditional graph (decision nodes, shares)')):
            if os.path.exists(os.path.join(conddir, name)):
                href = f'{conddir_rel}/{name}'
                figs.append(f'<div class="fig"><a href="{href}" target="_blank">'
                            f'<img src="{href}" loading="lazy"></a><div class="fig-cap">{cap}</div></div>')
        for i, s in enumerate(shapes):
            f = sig_file(sigdir, tag, i, s.get('signature') or '')
            if not f:
                continue
            c = int(s.get('count') or 0)
            ns = s.get('nodes') or []
            p = collections.Counter(n['pe'] for n in ns)
            href = f'{sigdir_rel}/{f}'
            sig_links.append(
                f'<div class="fig"><a href="{href}" target="_blank"><img src="{href}" loading="lazy"></a>'
                f'<div class="fig-cap"><span style="background:{CLASS_COLOR.get(cls.get(i, ""), "#777")};'
                f'color:#fff;border-radius:3px;padding:0 5px">{cls.get(i, "?")}</span> '
                f'sig {html.escape(str(s.get("signature"))[:8])} · ×{c} '
                f'({100.0*c/max(n_all,1):.1f} %) · {len(ns)}n '
                f'({p.get("CPU",0)}/{p.get("SM",0)}/{p.get("CE",0)}) · {html.escape(str(s.get("phase","?")))}</div></div>')

        ok = bool(A and A['drawable_skeleton'])
        skel = f"{len(A['bb'])}" if ok else '—'
        brn = f"{len(A['blocks'])}" if ok else '—'
        drop = (len(A['init']) + len(A['deg'])) if A else 0
        rowsum.append(
            f'<tr><td class="num">{k}</td>'
            f'<td><a href="#cb{k}"><b>{html.escape(nick)}</b></a></td>'
            f'<td><code>{html.escape(str(r["anchor"]))}</code></td>'
            f'<td class="num">{r["n_invocations"]}</td>'
            f'<td class="num">{len(shapes)}</td>'
            f'<td class="num">{100.0*int(dom.get("count") or 0)/max(n_all,1):.0f} %</td>'
            f'<td class="num">{len(dnodes)} ({pe.get("CPU",0)}/{pe.get("SM",0)}/{pe.get("CE",0)})</td>'
            f'<td class="num">{skel}</td><td class="num">{brn}</td>'
            f'<td class="num">{drop or ""}</td>'
            f'<td>{chips(by_cls)}</td>'
            f'<td>{" · ".join(html.escape(f"{p} {c}") for p, c in phases.most_common())}</td>'
            f'<td>{"".join(f"<a href={chr(34)}{conddir_rel}/{tag}_fig{i}.svg{chr(34)}>fig{i}</a> " for i in (1,2) if os.path.exists(os.path.join(conddir, f"{tag}_fig{i}.svg")))}'
            f'{f"<a href={chr(34)}{sigdir_rel}/index.html{chr(34)}>sigs</a>" if sig_links else ""}</td></tr>')

        sections.append(
            f'<div class="cb" id="cb{k}"><h2>#{k} <span class="nick">{html.escape(nick)}</span></h2>'
            f'<div class="label">{r["anchor_type"]} {html.escape(str(r["anchor"]))} · node '
            f'{html.escape(str(r["node"]))} · entity {html.escape(str(r["entity"]))}</div>'
            f'<div><span class="stats">{r["n_invocations"]} inv</span>'
            f'<span class="stats alt">{len(shapes)} signatures</span>'
            f'<span class="stats gold">|skel| {skel}</span>'
            f'<span class="stats grey">{brn} branch blocks</span>'
            + (f'<span class="stats grey">{drop} shapes not in skeleton</span>' if drop else '')
            + (f' <a href="{conddir_rel}/{tag}.txt">signature table</a>'
               if os.path.exists(os.path.join(conddir, f'{tag}.txt')) else '')
            + f'</div><div style="margin:.3em 0">{chips(by_cls)}</div>'
            + (f'<div class="figs">{"".join(figs)}</div>' if figs else
               '<div class="meta">no conditional figure (single signature or backbone too large)</div>')
            + (f'<div class="meta" style="margin-top:.6em">signatures</div><div class="figs">{"".join(sig_links)}</div>'
               if sig_links else '')
            + '</div>')

    extra = []
    for d, lab in ((session, 'callback / WCC graphs'), (session + '_isaac_unet', 'callback / WCC graphs')):
        if os.path.exists(os.path.join(root, d, 'index.html')):
            extra.append(f'<a href="{d}/index.html">{lab} ({d})</a>')
    if os.path.exists(os.path.join(conddir, 'index.html')):
        extra.append(f'<a href="{conddir_rel}/index.html">skeleton / conditional gallery</a>')
    if os.path.exists(os.path.join(sigdir, 'index.html')):
        extra.append(f'<a href="{sigdir_rel}/index.html">per-signature typed DAGs</a>')

    top_k = ' · '.join(f'{html.escape(disp("SM:" + n))} ×{c}' for n, c in kernels.most_common(6))
    body = (f'<h1>FISH GPU DAG index — {session}</h1>'
            f'<div class="meta">{len(rows)} GPU-submitting callbacks · {tot["inv"]} invocations · '
            f'{tot["sigs"]} signatures · {tot["ops"]} GPU operations '
            f'({tot.get("cpu",0)} CPU API / {tot.get("sm",0)} kernel / {tot.get("ce",0)} copy) · '
            f'{len(kernels)} distinct kernels · {len(copies)} copy kinds</div>'
            f'<div class="meta">hottest kernels: {top_k}</div>'
            f'<div class="meta">{" · ".join(extra)}</div>'
            f'<h2>Index</h2><table><tr><th>#</th><th>N ← E</th><th>anchor</th><th>inv</th><th>sigs</th>'
            f'<th>dominant</th><th>dominant DAG (CPU/SM/CE)</th><th>|skel|</th><th>branches</th>'
            f'<th>excl.</th><th>signature classes</th><th>phases</th><th>figures</th></tr>' + ''.join(rowsum) + '</table>'
            f'<div class="meta">|skel| = length of the backbone (LCS over the kept signatures); '
            f'branches = insertion blocks hanging off it; excl. = signatures left out of the skeleton '
            f'(INIT-phase or degenerate/aborted shapes), still drawn below.</div>'
            + ''.join(sections))
    path = os.path.join(root, f'{session}_index.html')
    open(path, 'w').write(f'<!DOCTYPE html><html><head><meta charset="utf-8">'
                          f'<title>FISH GPU DAG index — {session}</title><style>{CSS}</style></head>'
                          f'<body>{body}</body></html>')
    print(f'[index] {path}  ({len(rows)} callbacks, {tot["ops"]} GPU ops)')
    return path


def top_index(root=ROOT):
    items = []
    for f in sorted(os.listdir(root)):
        if f.endswith('_index.html'):
            s = f[:-len('_index.html')]
            items.append(f'<li><a href="{f}"><b>{s}</b> — full GPU DAG index</a></li>')
    for d in sorted(os.listdir(root)):
        if os.path.isdir(os.path.join(root, d)) and os.path.exists(os.path.join(root, d, 'index.html')):
            items.append(f'<li><a href="{d}/index.html">{d}</a></li>')
    open(os.path.join(root, 'index.html'), 'w').write(
        f'<!DOCTYPE html><html><head><meta charset="utf-8"><title>FISH DAG galleries</title>'
        f'<style>{CSS}</style></head><body><h1>FISH DAG galleries</h1>'
        f'<div class="meta">Full per-session indexes first, then the individual galleries they link to.</div>'
        f'<ul>{"".join(items)}</ul></body></html>')
    print(f'[index] {os.path.join(root, "index.html")}')


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('sessions', nargs='+'); ap.add_argument('--scope', default='__main__')
    ap.add_argument('--root', default=ROOT); ap.add_argument('--top', action='store_true')
    a = ap.parse_args()
    for s in a.sessions:
        session_index(s, a.scope, a.root)
    if a.top:
        top_index(a.root)


if __name__ == '__main__':
    main()
